    },
    {
      "id": "FAM:SF-APPS-090",
      "status_as_recorded": "untestable",
      "finding": "Connector diet x destination structural-gap match study: binary match rate 15.7%. Taxonomy CONNECTOR delta match vs mismatch not significant (p=0.156, n=5/14). All-movers binary delta significant but Spearman negative. Overall judged untestable due to small connector subsets (n=19/40) and failure to replicate as continuous. RISK:SAMPLE_SIZE_POWER."
    },
    {
      "id": "FAM:SF-APPS-024",
      "status_as_recorded": "untestable",
      "finding": "DRIVE-as-BEST counter vs constrained mix: n=44; observed gap -0.066 PPP vs MDE 0.180 PPP at 80% power. Result indistinguishable from null. Judged untestable due to low power and small sample."
    },
    {
      "id": "FAM:SF-PAP-029",
      "status_as_recorded": "untestable",
      "finding": "Destination outcome checks for movers: stated underpowered and null once corrected for landing-spot quality. No usable numbers. Dropped from Paper 1. Untestable."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPS-090",
      "what_failed": "Testing diet-matching of connectors to destination structural gaps",
