    "p_testable": 0.05,
    "blocking_constraints": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "n=24 shapers is too small to detect an effect of the magnitude seen in FAM:SF-CHT-057 (AUC 0.65, rho 0.27) with adequate power (>20% power at best)."
