      {
        "code": "EXPOSURE_SPARSITY",
        "text": "Cut-heavy and drive-heavy shapers may represent only a few players, making group comparisons infeasible."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Shaper classification depends on residual influence estimation; reliability in small samples and across seasons may be low."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": ["FAM:SF-CHT-057"],
    "summary": "FAM:SF-CHT-057 demonstrated that among connector movers, cut share positively and drive share negatively predict portability. This provides a partial answer for connectors but not for the narrower Shaper role. The present question refines to shapers; the prior work supports the direction but cannot substitute for a test with the available n=24."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "n=24 provides negligible power to detect the effect sizes observed in prior work; any null result would be uninformative; any significant result likely overestimated or a false positive."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Cut-heavy or drive-heavy shapers may be very rare; a median split or tercile comparison could produce empty or near-empty cells."
    },
    {
      "code": "CONFOUNDING",
      "text": "Movers are not randomly assigned; team system, roster construction, and player age/injury could drive both play-type profile and post-move success."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Players who move may be atypical (e.g., declining, fringe). Selecting only shapers who move could induce regression-to-the-mean in portability measures."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Multiple ways to define cut-heavy/drive-heavy and portability could inflate false positive rate if not pre-specified."
    }
  ],
  "predicted_outcome": {
    "supported": 0.02,
    "rejected": 0.03,
    "untestable": 0.85,
    "artifact": 0.05,
    "uncertain": 0.05
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Difference in portability (organizational function reproduction, Delta) between cut-heavy and drive-heavy shapers who move between seasons.",
    "unit": "Individual shaper mover (a player classified as Shaper in his origin season who moves to a different team).",
    "sample": "All shaper movers from the 2022-23 through 2025-26 seasons with ≥10 initiations in origin season and ≥10 in destination season, yielding approximately 24 players.",
    "power": "With n=24, power to detect the observed CHT-057 effect size (AUC 0.65, rho 0.27) is below 25% at alpha 0.05; to achieve 80% power would require a Cohen's d >1.1, which is implausible. Hence the test is not viable.",
    "controls": "None feasible given sample; but ideally adjust for origin team system, destination team system, minutes change, and age.",
    "falsification": "Permutation of cut-heavy/drive-heavy labels to test if observed difference exceeds chance, but with n=24 permutation distributions are coarse.",
    "multiplicity": "Specify a single primary test: Spearman correlation between pre-move cut-drive difference (or cut share) and post-move Delta. Avoid multiple operationalizations without adjustment.",
    "decision_rule": "Do not proceed; the minimum viable sample would be ~80 shaper movers, requiring many more seasons or a relaxation of the Shaper criterion to Connectors as in CHT-057.",
    "data_version": "NBA 2022-23 through 2025-26 regular season and playoffs, play-by-play and derived play-type initiation records, as available on 2026-08-08."
  }
}}

